def transform(grid):
    # The marker is a stencil: copy its pattern wherever the same cells are zero.
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in (0,9)]
    if not pts: return out
